mapper.update:
	UPDATE  /* isry.couns.constt.chttmng.mapper.InqSpclaMapper.updateSpcla : 특별관리대상자 게시글수정*/ 
	        AYB110 
	SET

            CLIENA_ID                  =       #{CLIENA_ID}


	    ,   CLIENA_NM_ENCPT            =       C##RG.ENC_B64(#{CLIENA_NM_ENCPT})


	    ,   DSCSN_DTL_CN               =       #{DSCSN_DTL_CN}


	    ,   CNSLTNT_ID                 =       #{CNSLTNT_ID}

	    ,   CNTN_IP_ADDR               =       #{CNTN_IP_ADDR}
	    ,   LAST_MDFR_ID               =       #{LAST_MDFR_ID}
	    ,   LAST_MDFCN_DT              =       SYSDATE
	WHERE   SPCLA_MNG_TRPR_SN          =       #{SPCLA_MNG_TRPR_SN}
